        { id: "l18k3", type: "count", front: "أمثلة الكتاب للعقود التي تحوي معنى التبرع ابتداءً والمعاوضة انتهاءً", n: 3, lead: "مثّل لها الكتاب بثلاثة عقود:", items: ["القرض", "الكفالة بأمر المدين", "الهبة بشرط العوض"], pg: "40" },
        { id: "l18k4", type: "count", front: "نوعا عقود التبرع", n: 2, lead: "تنقسم عقود التبرع إلى نوعين:", items: ["عقود الهبات: يترتب عليها افتقار الواهب", "عقود التفضل: لا يترتب عليها افتقار ذمة المتفضل"], pg: "40" },
        { id: "l18k5", type: "count", front: "ما ذكره الكتاب من العقود الممتزجة في عقد النزول في الفندق", n: 4, lead: "ذكر الكتاب منها أربعة:", items: ["الإيجار: للمسكن", "البيع: للمأكل والمشرب", "العمل: للخدمة التي تُقدَّم للنزيل", "الوديعة: لأمتعته"], pg: "40–41" },
        { id: "l18k6", type: "rule", front: "الأحكام التي تسري على العقد المختلط", rule: "تسري عليه أحكام العقود التي يشتمل عليها.", exc: "إذا تنافرت هذه الأحكام سرت عليه أحكام العقد الغالب، وهو العقد الأساسي فيه؛ كعقد التليفون، غلّب فيه القضاء عقد العمل على عقد الإيجار.", pg: "41" },
        { id: "l18k7", type: "rule", front: "حرية مناقشة شروط العقد", rule: "الأصل أن العقود كلها عقود مساومة، يناقش كل طرف شروطها قبل أن يرضى بها، لأن انعقادها يقوم على التراضي.", exc: "في عقود الإذعان يضع أحد الطرفين الشروط كلها، فلا يبقى للآخر إلا قبول الصفقة برمتها أو رفضها، دون حق في تعديلها.", pg: "41" },
        { id: "l18k8", type: "count", front: "شروط اعتبار العقد من عقود الإذعان", n: 4, lead: "يجب لاعتبار العقد من عقود الإذعان:", items: ["تعلق موضوعه بسلع أو مرافق ضرورية للمستهلكين أو المنتفعين", "احتكار الموجب لها احتكاراً قانونياً أو فعلياً", "صدور الإيجاب للناس كافة بشروط واحدة وعلى نحو مستمر", "استقلال أحد الطرفين استقلالاً تاماً بوضع الشروط"], pg: "41–42" },
        { id: "l18k9", type: "count", front: "ما يترتب على الصفة التبعية لعقدي الكفالة والرهن", n: 2, lead: "ذكر الكتاب أمرين:", items: ["نشوء الالتزام المضمون باطلاً يجعل عقد الرهن أو الكفالة باطلاً", "انقضاء الالتزام المضمون يقضي التزام الكفيل أو الراهن"], pg: "42" },
        { id: "l18k10", type: "def", front: "عقد المعاوضة", back: "هو العقد الذي يأخذ فيه كل من المتعاقدين مقابلاً لما يعطي.", bk: true, pg: "39", auto: true },
        { id: "l18k11", type: "def", front: "عقد التبرع", back: "هو العقد الذي لا يأخذ فيه المتعاقد مقابلاً لما أعطى، ولا يعطى فيه المتعاقد الآخر مقابلاً لما أخذه.", bk: true, pg: "39", auto: true },
        { id: "l18k12", type: "def", front: "عقود الهبات", back: "العقود التي يترتب عليها افتقار الواهب وذلك بإخراج مال معين من ذمته إلى المتبرع له.", bk: true, pg: "40", auto: true },
        { id: "l18k13", type: "def", front: "عقود التفضل", back: "التبرعات التي لا يترتب عليها افتقار ذمه المتفضل، كالتبرع بالمنافع والخدمات", bk: true, pg: "40", auto: true },
        { id: "l18k14", type: "def", front: "العقد البسيط", back: "هو الاتفاق الذي يقتصر على عقد واحد ولا تمتزج به عقود أخرى.", bk: true, pg: "40", auto: true },
        { id: "l18k15", type: "def", front: "العقد المختلط (المركب)", back: "هو العقد الذي يتكون من مزيج من عقود مختلفة اختلطت فأصبحت عقداً واحداً.", bk: true, pg: "40", auto: true },
        { id: "l18k16", type: "def", front: "عقد المساومة", back: "هو العقد الذي يكون لطرفيه أن يناقشا شروطه بحرية تامة قبل إبرامه،", bk: true, pg: "41", auto: true },
        { id: "l18k17", type: "def", front: "عقد الإذعان", back: "عقد يضع أحد طرفيه كل شروطه بصفة عامة، ويقبله الطرف الآخر دون أن تكون له حرية مناقشته أو طلب تعديله.", bk: true, pg: "41", auto: true },
        { id: "l18k18", type: "def", front: "العقد الأصلي", back: "هو ذلك العقد الذي يكون وجودة مستقلاً، فلا يقوم مستنداً على عقد آخر،", bk: true, pg: "42", auto: true },
        { id: "l18k19", type: "def", front: "العقد التبعي", back: "هو العقد الذي لا ينشأ مستقلاً بذاته وإنما ينشأ ضمانة لعقد آخر،", bk: true, pg: "42", auto: true },
        { id: "l18k20", type: "def", front: "عقد التوثيق", back: "ويقصد منه ضمان الديون لأصحابها.", bk: true, pg: "42", auto: true }
